const PRIORITIES = new Set(['low', 'normal', 'high']);
const ALLOWED_ARGS = new Set(['title', 'description', 'priority']);

let nextId = 1;

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }
  for (const key of Object.keys(args)) {
    if (!ALLOWED_ARGS.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  const { title, description, priority = 'normal' } = args;
  if (typeof title !== 'string' || title.length === 0) {
    throw new Error('title must be a non-empty string');
  }
  if (typeof description !== 'string' || description.length === 0) {
    throw new Error('description must be a non-empty string');
  }
  if (typeof priority !== 'string' || !PRIORITIES.has(priority)) {
    throw new Error('priority must be one of: low, normal, high');
  }
  return { title, description, priority };
}

export async function listTools() {
  return [
    {
      name: 'ticket_create',
      description: 'Create a support ticket with a title, description, and optional priority.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', minLength: 1, description: 'Short summary of the issue.' },
          description: { type: 'string', minLength: 1, description: 'Detailed description of the issue.' },
          priority: {
            type: 'string',
            enum: ['low', 'normal', 'high'],
            default: 'normal',
            description: 'Ticket priority.'
          }
        },
        required: ['title', 'description'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { priority } = validateArgs(args);
  const id = 't' + nextId++;
  return {
    content: [{ type: 'text', text: `Ticket ${id} created (priority: ${priority})` }]
  };
}

